`module.exports = function (inputs) {
  const src = (inputs && inputs.booking_json != null) ? inputs.booking_json : null;

  let b = null;
  try { b = (typeof src === 'string') ? JSON.parse(src) : src; } catch (e) { b = null; }

  const found = !!(b && (b.bookingReference || b.id));

  const status = found ? String(b.bookingStatus || '') : '';
  const alreadyCancelled = /CANCEL/i.test(status);

  // 1. Identite : l'email du demandeur doit etre celui de la reservation
  const bookingEmail = (found && b.customer) ? String(b.customer.email || '') : '';
  const norm = function (s) { return String(s == null ? '' : s).trim().toLowerCase(); };
  const requesterEmail = norm(inputs ? inputs.requester_email : '');
  const emailMatch = !!bookingEmail && norm(bookingEmail) === requesterEmail;

  // 2. Delai : la veille du 1er jour de location, 08h00 heure de Paris (07h00 UTC)
  let deadlineIso = '';
  let withinDeadline = false;
  const from = (found && b.rentalPeriod) ? b.rentalPeriod.from : null;
  if (from) {
    const start = new Date(from);
    if (!isNaN(start.getTime())) {
      const deadline = new Date(start.getTime() - 24 * 3600 * 1000);
      deadline.setUTCHours(7, 0, 0, 0);
      deadlineIso = deadline.toISOString();
      withinDeadline = Date.now() < deadline.getTime();
    }
  }

  const mayCancel = found && !alreadyCancelled && emailMatch && withinDeadline && String((inputs && inputs.intent) || '').toUpperCase() === 'CANCEL';

  const reason = !found           ? 'BOOKING_NOT_FOUND'
               : alreadyCancelled ? 'ALREADY_CANCELLED'
               : !emailMatch      ? 'EMAIL_MISMATCH'
               : !withinDeadline  ? 'DEADLINE_PASSED' : String((inputs && inputs.intent) || '').toUpperCase() !== 'CANCEL' ? 'NOT_A_FULL_CANCELLATION'
               : 'OK';
  return {
    may_cancel: mayCancel,
    reason: reason,
    booking_id: found ? String(b.id || '') : '',
    booking_reference: found ? String(b.bookingReference || '') : '',
    booking_status: status,
    customer_email: bookingEmail,
    rental_from: from ? String(from) : '',
    cancel_deadline: deadlineIso
  };
};`

