`module.exports = function (inputs) {
  // Two Odin answers arrive here and one refund call leaves.
  //
  // \`output\` is First Captured Payment - the payment object, or null when the
  // booking was never captured (paid in the shop, or expired before payment).
  // \`refund\` is Get Refundable Amount (Payment) - what Odin will still allow
  // back on that payment right now.
  //
  // Both are parsed from text rather than read as objects, because the MCP steps
  // hand the whole response over as one blob.
  var asRaw = function (v) {
    if (v == null) return '';
    return (typeof v === 'string') ? v : JSON.stringify(v);
  };

  var pay = asRaw(inputs && inputs.output).replace(/\\\\\\\\/g, '');
  var ref = asRaw(inputs && inputs.refund).replace(/\\\\\\\\/g, '');

  // A uuid is unambiguous in this payload. Matching the "id" key by name would
  // also match bookingId, cartId and every other id the object carries.
  var pm = pay.match(/"id"\\s*:\\s*"([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})"/);
  var pid = pm ? pm[1] : '';

  var am = ref.match(/"amount"\\s*:\\s*(-?[0-9]+)/);
  var cm = ref.match(/"currency"\\s*:\\s*"([A-Za-z]{3})"/);
  var minor = am ? parseInt(am[1], 10) : 0;
  var cur = cm ? cm[1].toUpperCase() : '';

  // Every one of these has to hold before a gateway call is worth making: a
  // payment to refund, a positive amount, and a currency to state it in. A
  // refund of 0 is not a refund, and an amount without a currency is a guess.
  var ok = pid !== '' && minor > 0 && cur !== '';

  return {
    payment_id: pid,
    can_refund: ok,
    // Shaped exactly as payment_refund expects it, because amountToRefund is an
    // Object input and Zendesk will only bind an Object-typed variable to it.
    refund_amount: { amount: minor, currency: cur }
  };
};
`

